#!/usr/bin/env python3"""Тест создания папки с чатами"""import requestsimport json# Настройкиbase_url = "http://localhost:8000"test_user = {    "username": "testuser",    "email": "test@example.com",     "password": "testpassword123"}def test_folder_creation_with_chats():    """Тест создания папки с чатами"""    print("🚀 Тест создания папки с чатами")    print("=" * 50)        try:        # Проверяем доступность сервера        print("🔍 Проверяем доступность сервера...")        response = requests.get(f"{base_url}/", timeout=5)        if response.status_code != 200:            print("❌ Сервер недоступен")            return False        print("✅ Сервер доступен")                # Регистрируем пользователя        print("\n👤 Регистрируем пользователя...")        response = requests.post(f"{base_url}/register", json=test_user, timeout=5)        if response.status_code == 201:            print("✅ Пользователь зарегистрирован")        elif response.status_code == 400:            print("⚠️ Пользователь уже существует")        else:            print(f"❌ Ошибка регистрации: {response.status_code}")            return False                # Авторизуемся        print("\n🔐 Авторизуемся...")        response = requests.post(f"{base_url}/login",                                data={"username": test_user["username"],                                      "password": test_user["password"]},                                timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка авторизации: {response.status_code}")            return False                token = response.json()["access_token"]        headers = {"Authorization": f"Bearer {token}"}        print("✅ Авторизация успешна")                # Получаем список агентов        print("\n🤖 Получаем список агентов...")        response = requests.get(f"{base_url}/agents", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка получения агентов: {response.status_code}")            return False                agents = response.json()        if not agents:            print("❌ Агенты не найдены")            return False                agent = agents[0]        print(f"✅ Найден агент: {agent['name']} (ID: {agent['id']})")                # Создаем чат        print("\n💬 Создаем чат...")        response = requests.post(f"{base_url}/chats",                                json={"agent_id": agent["id"]},                                headers=headers, timeout=5)        if response.status_code != 201:            print(f"❌ Ошибка создания чата: {response.status_code}")            return False                chat = response.json()        print(f"✅ Чат создан с ID: {chat['id']}")                # Создаем папку с чатом        print("\n📁 Создаем папку с чатом...")        folder_data = {            "name": "Тестовая папка с чатом",            "description": "Папка для тестирования",            "folder_type": "custom",            "icon": "folder",            "color": "bg-blue-500",            "chat_ids": [chat["id"]],            "agent_ids": [agent["id"]]        }                response = requests.post(f"{base_url}/folders",                                json=folder_data,                                headers=headers, timeout=5)        if response.status_code != 201:            print(f"❌ Ошибка создания папки: {response.status_code}")            print(f"Ответ: {response.text}")            return False                folder = response.json()        print(f"✅ Папка создана с ID: {folder['id']}")        print(f"📊 Количество чатов в папке: {folder['chat_count']}")                # Проверяем содержимое папки        print("\n🔍 Проверяем содержимое папки...")        response = requests.get(f"{base_url}/folders/{folder['id']}", headers=headers, timeout=5)        if response.status_code != 200:            print(f"❌ Ошибка получения папки: {response.status_code}")            return False                folder_details = response.json()        print(f"✅ Папка получена: {folder_details['name']}")        print(f"📊 Количество чатов: {folder_details['chat_count']}")                # Проверяем, что чат действительно в папке        if folder_details['chat_count'] > 0:            print("✅ Чат успешно добавлен в папку при создании!")        else:            print("❌ Чат не был добавлен в папку при создании")            return False                print("\n🎉 Все тесты прошли успешно!")        return True            except Exception as e:        print(f"❌ Ошибка: {e}")        return Falseif __name__ == "__main__":    if test_folder_creation_with_chats():        print("\n✅ Тест завершен успешно!")    else:        print("\n❌ Тест не прошел!")